def _replay_chunks_sampling(
    workers_intervals: Dict[int, List[Any]], indexes: Dict[int, int]
) -> Tuple[Dict[int, int], Dict[int, int]]:

    chunks_index = {}
    for worker_idx, intervals in workers_intervals.items():
        current_index = indexes[worker_idx]
        chunk_idx = 0
        for interval in intervals:
            interval_size = interval[1] - interval[0]
            if current_index < interval_size:
                break
            current_index -= interval_size
            chunk_idx += 1
        chunks_index[worker_idx] = chunk_idx
        indexes[worker_idx] = current_index

    return chunks_index, indexes
