def filter_by_threshold(results, value, threshold, metadatas=None) -> Tuple[List, List]:
    if metadatas is None:
        metadatas = [None] * len(results)
    filtered_results = []
    filtered_metadatas = []
    for res, val, meta in zip(results, value, metadatas):
