def format_measure(x: float, percent: bool = False) -> str:
    """
    Formats a given number into a user-friendly string, optionally converting it into a percentage format. It dynamically adjusts the number of decimal places based on the value of the number.

    Input-Output Arguments
    :param x: float, The number to be formatted.
    :param percent: bool, default=False, Determines if the number should be formatted as a percentage. If True, the number is multiplied by 100 and a percentage sign is added.
    :return: str, The formatted string representation of the number. If the input number is NaN, it returns the string representation of NaN. Otherwise, it returns the number formatted with a dynamic number of decimal places, optionally as a percentage.
    """
    if np.isnan(x):
        return str(x)
    val = x * 100 if percent else x
    abs_val = abs(val)
    if abs_val >= 100:
        decimals = 0
    elif abs_val >= 10:
        decimals = 1
    elif abs_val >= 1:
        decimals = 2
    elif abs_val >= 0.1:
        decimals = 3
    else:
        decimals = 4
    formatted = f"{val:.{decimals}f}"
    if percent:
        formatted += "%"
    return formatted
