@contextmanager
def freeze_training_mode(model):
    """
    This function temporarily sets the "training" attribute of every submodule in a given model to a constant value, allowing for optimization by meta-compilation. It uses a context manager to ensure that these changes are reverted back to their original state after the context manager exits.
    Input-Output Arguments
    :param model: The model whose submodules' "training" attributes are to be temporarily annotated as constants. It is used to iterate through all submodules and modify their class definitions.
    :return: No return values. This function operates by side effects, modifying the class definitions of the model's submodules within the context.
    """
    orig_training = {}
    orig_annotations = {}

    try:
        for module in model.modules():
            cls = module.__class__
            if cls not in orig_training:
                orig_training[cls] = cls.training if hasattr(cls, "training") else None
                orig_annotations[cls] = getattr(cls, "__annotations__", None)
                # Annotate training as a constant attribute for scripting
                cls.training = torch.jit.Final[module.training]
                if orig_annotations[cls] is None:
                    cls.__annotations__ = {"training": torch.jit.Final[bool]}
                else:
                    cls.__annotations__["training"] = torch.jit.Final[bool]
        yield
    finally:
        for cls, val in orig_training.items():
            if val is None:
                if hasattr(cls, "training"):
                    delattr(cls, "training")
            else:
                cls.training = val
        for cls, ann in orig_annotations.items():
            if ann is None:
                if hasattr(cls, "__annotations__"):
                    delattr(cls, "__annotations__")
            else:
                cls.__annotations__ = ann
