def cast_metrics(metrics: Union[List[str], List[Dict]]) -> Tuple[List[str], List[Dict[str, Any]]]:
    metric_names = []
    metric_params = []

    if not isinstance(metrics, list):
        raise ValueError(f"metrics must be a list, but got {type(metrics)}")

    for metric in metrics:
        if isinstance(metric, str):
            metric_names.append(metric)
            metric_params.append({})
        elif isinstance(metric, dict):
            if len(metric) != 1:
                raise ValueError(f"Each metric dict must have exactly one key, but got {metric}")
            for name, params in metric.items():
                metric_names.append(name)
                if params is None:
                    metric_params.append({})
                elif isinstance(params, dict):
                    metric_params.append(params)
                else:
                    raise ValueError(f"Metric parameters must be a dict or None, but got {type(params)}")
        else:
            raise ValueError(f"Each metric must be either a string or a dict, but got {type(metric)}")

    return metric_names, metric_params
