        lock_path = local_filepath + ".lock"
        lock = FileLock(lock_path, timeout=60)
        try:
            with lock:
                if os.path.exists(local_filepath):
                    return

                if self._s5cmd_available:
                    cmd = ["s5cmd", "cp", remote_filepath, local_filepath]
                    subprocess.run(cmd, check=True)
                else:
                    bucket = parsed_url.netloc
                    key = parsed_url.path.lstrip("/")
                    self._client.download_file(bucket, key, local_filepath)
        except Timeout:
            raise Timeout(f"Timeout while waiting for the lock on {lock_path}")
