def _assert_dir_has_index_file(output_dir: Dir) -> None:
    if not isinstance(output_dir, Dir):
        raise ValueError("The provided output_dir isn't a Dir Object.")

    if output_dir.url is None:
        raise ValueError("The provided output_dir.url is None.")

    obj = parse.urlparse(output_dir.url)

    if obj.scheme != "s3":
        raise ValueError(f"The provided folder should start with s3://. Found {output_dir.path}.")

    s3 = boto3.client("s3")

    prefix = obj.path.lstrip("/").rstrip("/") + "/"

    objects = s3.list_objects_v2(
        Bucket=obj.netloc,
        Prefix=prefix,
    )

    if "Contents" not in objects or len(objects["Contents"]) == 0:
        raise RuntimeError(f"The provided output_dir `{output_dir.path}` does not contain any files.")

    index_file_found = any(obj["Key"] == prefix + "index.json" for obj in objects["Contents"])

    if index_file_found:
        raise RuntimeError(
            f"The provided output_dir `{output_dir.path}` already contains an index file 'index.json'."
            " HINT: Did you consider changing the `output_dir` with your own versioning as a suffix?"
        )

    # Delete all objects under the prefix
