def _download_data_target(input_dir: Dir, cache_dir: str, queue_in: Queue, queue_out: Queue) -> None:
    while True:
        task = queue_in.get()
        if task is None:
            return

        index, paths = task

        for path in paths:
            # Determine the local cache path for the file
            if input_dir.path and path.startswith(input_dir.path):
                relative_path = os.path.relpath(path, input_dir.path)
            else:
                relative_path = os.path.basename(path)

            local_path = os.path.join(cache_dir, relative_path)

            # Skip if file already exists locally
            if os.path.exists(local_path):
                continue

            # Create directories if needed
            os.makedirs(os.path.dirname(local_path), exist_ok=True)

            # Download the file from input_dir to local_path
            if input_dir.url:
                obj = parse.urlparse(input_dir.url)
                s3 = S3Client()
                bucket = obj.netloc
                prefix = obj.path.lstrip("/")
                # Construct the key relative to the input_dir url path
                key = os.path.join(prefix, relative_path).replace("\\", "/")
                try:
                    with open(local_path, "wb") as f:
                        s3.client.download_fileobj(bucket, key, f)
                except Exception as e:
                    logger.error(f"Failed to download {key} from bucket {bucket}: {e}")
                    raise
            else:
                # If no url, assume local copy
                if os.path.exists(path):
                    shutil.copy2(path, local_path)
                else:
                    raise FileNotFoundError(f"File {path} does not exist and no url provided for download.")

        queue_out.put(index)
