    def load_function_description(func_object) -> FunctionDescription:

        """
        This function creates a description of a given function object, including its name, docstring, input and output type hints, and class definitions for those types. It is designed to facilitate the registration of the function by providing detailed metadata about it. The function also determines the function type based on the output type hint, distinguishing between symbolic functions and those that can be embedded.

        Input-Output Arguments
        :param func_object: The function object to create a description for. It is used to extract the signature, type hints, and docstring of the function.
        :return: FunctionDescription. An instance of FunctionDescription containing the function's metadata, including its name, docstring, input and output type hints, class definitions for input and output types, and the function type (symbolic or embeddable).

        Additional details:
        - The function uses the `inspect.signature` method to get the function's signature and `get_type_hints` to fetch the type hints.
        - It differentiates between input and output type hints based on the function's signature.
        - A helper function `get_class_definition` is used to fetch class definitions for the type hints, handling generic types and ensuring that class definitions are fetched for non-built-in types.
        - The function checks if the output type hint is a class or a subclass of a Union and processes it accordingly to determine the function type and output class definition.
        - The function type can be either SYMBOLIC or EMBEDDABLE, determined based on whether the output type hint is a subclass of an Embedding class or part of a Union type.
        - The function's output, `FunctionDescription`, is a structured representation of the function's metadata, designed for use in function registration processes.
        """

        def get_class_definition(tp):
            origin = get_origin(tp)
            if origin is not None:
                # For generic types, get the origin class definition and also for args
                origin_def = get_class_definition(origin)
                args = getattr(tp, "__args__", None)
                if args:
                    args_defs = [get_class_definition(arg) for arg in args]
                    return {"origin": origin_def, "args": args_defs}
                else:
                    return origin_def
            elif inspect.isclass(tp):
                # For classes, get source if not builtin
                if hasattr(tp, "__module__") and tp.__module__ == "builtins":
                    return None
                try:
                    source = get_source(tp)
                    return source
                except Exception:
                    return None
            else:
                return None

        sig = inspect.signature(func_object)
        type_hints = get_type_hints(func_object)

        input_type_hints = {}
        for param_name, param in sig.parameters.items():
            if param_name in type_hints:
                input_type_hints[param_name] = type_hints[param_name]

        output_type_hint = type_hints.get('return', None)

        input_class_definitions = {}
        for key, tp in input_type_hints.items():
            class_def = get_class_definition(tp)
            if class_def is not None:
                input_class_definitions[key] = class_def

        output_class_definition = None
        function_type = FunctionType.SYMBOLIC

        if output_type_hint is not None:
            origin = get_origin(output_type_hint)
            if origin is Union:
                # Check if any of the union types is subclass of Embedding
                args = getattr(output_type_hint, "__args__", ())
                embeddable_found = False
                for arg in args:
                    if inspect.isclass(arg) and issubclass(arg, Embedding):
                        embeddable_found = True
                        break
                if embeddable_found:
                    function_type = FunctionType.EMBEDDABLE
                output_class_definition = get_class_definition(output_type_hint)
            elif inspect.isclass(output_type_hint):
                if issubclass(output_type_hint, Embedding):
                    function_type = FunctionType.EMBEDDABLE
                output_class_definition = get_class_definition(output_type_hint)
            else:
                output_class_definition = get_class_definition(output_type_hint)

        func_name = func_object.__name__
        docstring = inspect.getdoc(func_object) or ""

        return FunctionDescription(
            name=func_name,
            docstring=docstring,
            input_type_hints=input_type_hints,
            output_type_hint=output_type_hint,
            input_class_definitions=input_class_definitions,
            output_class_definition=output_class_definition,
            type=function_type
        )
