    def generate(self, model, system_message, prompt, **kwargs):
        self.check_api_key()

        # Validate and prepare generation parameters
        generation_params = {}
        for param in LLM_GENERATION_PARAMETERS:
            if param in kwargs:
                generation_params[param] = kwargs[param]

