        if "max_new_tokens" in generation_params:
            generation_params["max_tokens"] = generation_params.pop("max_new_tokens")

        # Prepare messages for chat completion
        messages = [
            {"role": "system", "content": system_message},
            {"role": "user", "content": prompt}
        ]

        max_retries = 5
        backoff = 1  # initial backoff in seconds

        for attempt in range(max_retries):
            try:
                response = self.client.chat.completions.create(
                    model=model.model_name,
                    messages=messages,
                    **generation_params
                )
                # Extract the generated text from the response
                choices = response.choices
                if not choices or len(choices) == 0:
                    raise ValueError("No choices returned from OpenAI API")

                generated_text = choices[0].message.content

                # Remove parsing helper tokens if specified in model
                if hasattr(model, "parsing_helper_tokens") and model.parsing_helper_tokens:
                    for token in model.parsing_helper_tokens:
                        generated_text = generated_text.replace(token, "")

                return generated_text

            except Exception as e:
                logging.warning(f"OpenAI API call failed on attempt {attempt + 1}/{max_retries}: {e}")
                if attempt == max_retries - 1:
                    raise
                time.sleep(backoff)
                backoff *= 2  # exponential backoff
