    def draw_dataset_dict(self, dic):
        """
        This function visualizes the annotations/segmentations of an image based on the Detectron2 Dataset format. It handles different types of annotations including segmentation masks, keypoints, bounding boxes, semantic segmentation, and panoptic segmentation. The visualizations are drawn on the image, and the modified image object is returned.

        Input-Output Arguments
        :param self: Visualizer. An instance of the Visualizer class, which contains methods for drawing different types of annotations on images.
        :param dic: dict, The annotation/segmentation data for a single image, formatted according to the Detectron2 Dataset specifications. This dictionary may contain keys for annotations, semantic segmentation, and panoptic segmentation, among others.
        :return: VisImage, The image object with the visualizations drawn on it. This includes any combination of segmentation masks, keypoints, bounding boxes, semantic segmentation, and panoptic segmentation based on the input dictionary.

        """
        if "annotations" in dic:
            annotations = dic["annotations"]
            # Convert annotations to Instances object for drawing
            from detectron2.structures import Instances

            height, width = self.output.height, self.output.width
            instances = Instances((height, width))
            # Boxes
            boxes = []
            classes = []
            scores = []
            masks = []
            keypoints = []
            for ann in annotations:
                if "bbox" in ann:
                    bbox = ann["bbox"]
                    bbox_mode = ann.get("bbox_mode", BoxMode.XYWH_ABS)
                    # Convert bbox to XYXY_ABS
                    if bbox_mode == BoxMode.XYWH_ABS:
                        x0, y0, w, h = bbox
                        bbox_xyxy = [x0, y0, x0 + w, y0 + h]
                    elif bbox_mode == BoxMode.XYXY_ABS:
                        bbox_xyxy = bbox
                    else:
                        bbox_xyxy = BoxMode.convert(bbox, bbox_mode, BoxMode.XYXY_ABS)
                    boxes.append(bbox_xyxy)
                else:
                    boxes.append(None)
                classes.append(ann.get("category_id", None))
                scores.append(ann.get("score", None))
                # Masks
                if "segmentation" in ann:
                    masks.append(ann["segmentation"])
                elif "segmentation_rle" in ann:
                    masks.append(ann["segmentation_rle"])
                elif "segmentation_mask" in ann:
                    masks.append(ann["segmentation_mask"])
                else:
                    masks.append(None)
                # Keypoints
                if "keypoints" in ann:
                    keypoints.append(ann["keypoints"])
                else:
                    keypoints.append(None)

            # Filter out None boxes
            valid_boxes = [b for b in boxes if b is not None]
            if valid_boxes:
                instances.pred_boxes = Boxes(torch.tensor(valid_boxes, dtype=torch.float32))
            if any(c is not None for c in classes):
                instances.pred_classes = torch.tensor(
                    [c if c is not None else -1 for c in classes], dtype=torch.int64
                )
            if any(s is not None for s in scores):
                instances.scores = torch.tensor(
                    [s if s is not None else 0.0 for s in scores], dtype=torch.float32
                )
            # Masks
            if any(m is not None for m in masks):
                # Convert masks to GenericMask list
                generic_masks = []
                for m in masks:
                    if m is None:
                        continue
                    generic_masks.append(GenericMask(m, height, width))
                if generic_masks:
                    instances.pred_masks = generic_masks
            # Keypoints
            if any(kp is not None for kp in keypoints):
                valid_keypoints = [kp for kp in keypoints if kp is not None]
                if valid_keypoints:
                    instances.pred_keypoints = Keypoints(torch.tensor(valid_keypoints))
            return self.draw_instance_predictions(instances)

        if "sem_seg" in dic:
            sem_seg = dic["sem_seg"]
            return self.draw_sem_seg(sem_seg)

        if "panoptic_seg" in dic and "segments_info" in dic:
            panoptic_seg = dic["panoptic_seg"]
            segments_info = dic["segments_info"]
            return self.draw_panoptic_seg(panoptic_seg, segments_info)

        return self.output
