def assert_instances_allclose(input, other, *, rtol=1e-5, msg="", size_as_tensor=False):
    if size_as_tensor:
        assert torch.allclose(
            torch.tensor(input.image_size), torch.tensor(other.image_size), rtol=rtol
        ), f"{msg} image_size mismatch: {input.image_size} vs {other.image_size}"
    else:
        assert input.image_size == other.image_size, f"{msg} image_size mismatch: {input.image_size} vs {other.image_size}"

    input_fields = set(input.get_fields())
    other_fields = set(other.get_fields())
    assert input_fields == other_fields, f"{msg} field names mismatch: {input_fields} vs {other_fields}"

    for field in input_fields:
        input_val = input.get(field)
        other_val = other.get(field)

        if isinstance(input_val, Boxes):
            assert isinstance(other_val, Boxes), f"{msg} field {field} type mismatch: {type(input_val)} vs {type(other_val)}"
            assert torch.allclose(input_val.tensor, other_val.tensor, rtol=rtol), f"{msg} field {field} mismatch"
        elif isinstance(input_val, ROIMasks):
            assert isinstance(other_val, ROIMasks), f"{msg} field {field} type mismatch: {type(input_val)} vs {type(other_val)}"
            assert input_val.tensor.shape == other_val.tensor.shape, f"{msg} field {field} shape mismatch: {input_val.tensor.shape} vs {other_val.tensor.shape}"
            assert torch.allclose(input_val.tensor, other_val.tensor, rtol=rtol), f"{msg} field {field} mismatch"
        elif isinstance(input_val, torch.Tensor):
            assert isinstance(other_val, torch.Tensor), f"{msg} field {field} type mismatch: {type(input_val)} vs {type(other_val)}"
            assert torch.allclose(input_val, other_val, rtol=rtol), f"{msg} field {field} mismatch"
        else:
            if input_val != other_val:
                raise AssertionError(f"{msg} field {field} mismatch: {input_val} vs {other_val}")
