def lazy_trace(func, *, ts_compiler=None, **kwargs_):
    cache = {}
    lock = threading.Lock()

    def wrapper(*args, **kwargs):
        key = (hash_arg(args), hash_arg(kwargs))
        with lock:
            if key in cache:
                return cache[key](*args, **kwargs)
        # Compile outside the lock to avoid blocking other threads
        compiler = AutoTraceCompiler(ts_compiler=ts_compiler, **kwargs_)
        compiled_func = compiler.compile(func, args, kwargs)
        with lock:
            cache[key] = compiled_func
        return compiled_func(*args, **kwargs)

    return wrapper
