def parse_min_should_match(num_clauses: int, spec: str) -> int:
    if not spec:
        return 0

    spec = spec.strip()
    # If spec is a simple integer string
    if spec.isdigit():
        return min(num_clauses, int(spec))

    # If spec is a percentage string like "50%"
    if spec.endswith('%'):
        try:
            percent = float(spec[:-1])
            if percent < 0:
                # Negative percentage means complement
                val = int(round(num_clauses * (1 + percent / 100)))
            else:
                val = int(round(num_clauses * (percent / 100)))
            return min(num_clauses, max(0, val))
        except ValueError:
            return 0

    # If spec contains conditional expressions like "2<-25% 9<-3"
    # Parse multiple conditions separated by spaces
    conditions = spec.split()
    for cond in conditions:
        if '<' in cond:
            left, right = cond.split('<', 1)
            try:
                left_val = int(left)
            except ValueError:
                continue
            # Evaluate right side which can be percentage or integer
            right_val = None
            if right.endswith('%'):
                try:
                    percent = float(right[:-1])
                    if percent < 0:
                        right_val = int(round(num_clauses * (1 + percent / 100)))
                    else:
                        right_val = int(round(num_clauses * (percent / 100)))
                except ValueError:
                    continue
            else:
                try:
                    right_val = int(right)
                except ValueError:
                    continue
            if num_clauses <= left_val:
                return min(num_clauses, max(0, right_val))

    # If no condition matched, try to parse as integer or percentage again
    if spec.isdigit():
        return min(num_clauses, int(spec))
    if spec.endswith('%'):
        try:
            percent = float(spec[:-1])
            if percent < 0:
                val = int(round(num_clauses * (1 + percent / 100)))
            else:
                val = int(round(num_clauses * (percent / 100)))
            return min(num_clauses, max(0, val))
        except ValueError:
            return 0

    # Default fallback
    try:
        val = int(spec)
        return min(num_clauses, val)
    except ValueError:
        return 0
